<script setup>import AppShell from '@/Components/AppShell.vue';import{useForm,Link}from'@inertiajs/vue3';import{computed}from'vue';const p=defineProps({submission:Object});const choices=computed(()=>p.submission.status==='SUBMITTED'?['APPROVED','REVISION','REJECTED']:p.submission.status==='APPROVED'?['RELEASED']:[]);const labels={APPROVED:'Disetujui',REVISION:'Perlu Revisi',REJECTED:'Ditolak',RELEASED:'Released'};const f=useForm({status:choices.value[0]||'',coordinator_note:''});const send=()=>f.patch('/coordinator/submission/'+p.submission.id+'/status');const doc=id=>'/documents/'+id;const all='/submissions/'+p.submission.id+'/documents/download-all';</script>
<template><AppShell title="Review Pengajuan" :subtitle="submission.submission_number" eyebrow="Koordinator Sarana"><div class="mb-4 flex flex-wrap justify-between gap-3"><Link :href="'/coordinator/submissions/'+submission.type" class="btn-ghost">← Kembali</Link><a :href="all" class="btn">↓ Download Semua Dokumen</a></div><div class="grid gap-5 lg:grid-cols-3"><section class="panel lg:col-span-2"><h2 class="text-2xl font-black">{{submission.vendor_name}}</h2><p class="mt-1 text-sm text-slate-500">{{submission.applicant_name}} · {{submission.phone}}</p><p class="mt-4">{{submission.description||'-'}}</p><div class="mt-6 grid gap-3 md:grid-cols-2"><div v-for="d in submission.documents" class="rounded-xl border border-slate-200 p-4"><div class="flex justify-between gap-3"><div><b>{{d.document_name}}</b><p class="mt-1 text-xs text-slate-500">{{d.is_required?'Wajib':'Opsional'}} · {{(d.file_size/1048576).toFixed(2)}} MB</p></div><a :href="doc(d.id)" target="_blank" class="font-bold text-red-600">PDF</a></div></div></div></section><form class="panel h-fit" @submit.prevent="send"><h3 class="font-black">AKSI PENGAJUAN</h3><p class="mt-1 text-xs text-slate-500">Status saat ini: {{submission.status}}</p><template v-if="choices.length"><label class="mt-5 block text-sm font-bold">Status baru<select v-model="f.status" class="field select-control"><option v-for="status in choices" :value="status">{{labels[status]}}</option></select></label><label class="mt-4 block text-sm font-bold">Catatan Koordinator<textarea v-model="f.coordinator_note" class="field" rows="4" placeholder="Berikan catatan yang jelas"/></label><p class="err">{{f.errors.coordinator_note}}</p><button class="btn mt-4 w-full">Simpan Status</button></template><p v-else class="mt-5 rounded-xl bg-slate-50 p-4 text-sm text-slate-500">Pengajuan sudah berada pada status final.</p></form></div></AppShell></template>
